def esc(value: str) -> str:
    return html.escape(value, quote=True)


def add_analytics(text: str) -> str:
    if "G-VLZMV8Y4JP" not in text:
        text = text.replace("<head>", "<head>\n" + GA_SNIPPET, 1)
    return text


def enrich_comparison(text: str, slug: str, title: str) -> str:
    note = COMPARISON_NOTES.get(slug)
    if not note:
        return text
    left_def, right_def, left_signal, right_signal, question = note
    clean = re.sub(r"[؟?].*$", "", title)
    left, right = (part.strip() for part in clean.split(" أم ", 1))
    text = re.sub(
        r"<tr><th>الفكرة الأساسية</th><td>.*?</td><td>.*?</td></tr>",
        f"<tr><th>الفكرة الأساسية</th><td>{esc(left_def)}</td><td>{esc(right_def)}</td></tr>",
        text,
        count=1,
        flags=re.DOTALL,
    )
    unique = (
        '<section class="article-section two" data-comparison-quality="pair-specific-v3">'
        f'<article><h2>إشارة تميل إلى {esc(left)}</h2><p>{esc(left_signal)}</p></article>'
        f'<article><h2>إشارة تميل إلى {esc(right)}</h2><p>{esc(right_signal)}</p></article>'
        '</section>'
        '<section class="article-section answer-box">'
        '<h2>السؤال الحاسم</h2>'
        f'<p>{esc(question)}</p>'
        '</section>'
    )
    text = re.sub(
        r'<section class="article-section two"><article>.*?</section>',
        unique,
        text,
        count=1,
        flags=re.DOTALL,
    )
    return text


def enrich_five(text: str, title: str) -> str:
    p = profile(title)
    pattern = re.compile(r"(<article class='point-card'><span>(\d+)</span><h3>.*?</h3><p>)(.*?)(</p></article>)", re.DOTALL)
    def replace(match: re.Match[str]) -> str:
        index = max(0, min(int(match.group(2)) - 1, 4))
        explanation = f"قد يظهر أثر هذا العامل في {p['markers'][index]}. راقب السياق والتكرار بدل افتراض السبب، والخطوة العملية الأقرب هي: {p['actions'][index]}."
        return match.group(1) + esc(explanation) + match.group(4)
    return pattern.sub(replace, text)


def enrich_standard(text: str, title: str) -> str:
    p = profile(title)
    pattern = re.compile(r"(<article class='point-card'><span>(\d+)</span><h3>.*?</h3><p>)راقب تكرار هذا النمط وسياقه وأثره، ولا تحكم من موقف واحد\.(</p></article>)", re.DOTALL)
    def replace(match: re.Match[str]) -> str:
        index = max(0, min(int(match.group(2)) - 1, 4))
        explanation = f"يصبح هذا المؤشر أكثر أهمية عندما يتكرر مع {p['factors'][index]}. بدل الحكم السريع، جرّب هذه الخطوة: {p['actions'][index]}."
        return match.group(1) + esc(explanation) + match.group(3)
    return pattern.sub(replace, text)


def contextual_section(title: str) -> str:
    p = profile(title)
    points = [
        f"اسأل عن المدة: هل هو موقف عابر أم نمط يتكرر؟ راقب خصوصًا {p['markers'][0]}.",
        f"اسأل عن السياق: قد يرتبط الأمر بـ{p['factors'][1]}، لكن وجود العامل لا يثبت أنه السبب الوحيد.",
        f"اسأل عن الأثر: إذا تأثر النوم أو العمل أو الدراسة أو العلاقات، ابدأ بـ{p['actions'][2]} ثم اطلب تقييمًا عند الاستمرار.",
    ]
    items = "".join(f"<li>{esc(point)}</li>" for point in points)
    return '<section class="article-section context-section" data-quality="enriched-v2"><h2>كيف تفهم هذا في سياقك؟</h2>' + f'<ul>{items}</ul>' + '<p class="micro-note">المعلومة الأكثر فائدة ليست اسم الشعور وحده، بل متى بدأ، وما الذي يزيده، وكيف يغيّر قدرتك على العيش بأمان ومرونة.</p></section>'


def keep_homepage_outline_concise() -> None:
    path = ROOT / "index.html"
    text = path.read_text(encoding="utf-8")
    replacements = {
        '<h3 class="item-title">حزن أم اكتئاب؟</h3>': '<strong class="item-title">حزن أم اكتئاب؟</strong>',
        '<h3 class="item-title">إرهاق أم كسل؟</h3>': '<strong class="item-title">إرهاق أم كسل؟</strong>',
        '<h3 class="item-title">هل العلاقة آمنة؟</h3>': '<strong class="item-title">هل العلاقة آمنة؟</strong>',
        '<h3 class="item-title">فحص الصحة النفسية</h3>': '<strong class="item-title">فحص الصحة النفسية</strong>',
    }
    for old, new in replacements.items():
        text = text.replace(old, new)
    path.write_text(text, encoding="utf-8")


def main() -> None:
    changed = 0
    comparisons = 0
    for slug, title, kind, _category in TOPICS:
        path = OUT / slug / "index.html"
        text = add_analytics(path.read_text(encoding="utf-8"))
        if kind == "comparison":
            text = enrich_comparison(text, slug, title)
            comparisons += 1
        elif kind == "five":
            text = enrich_five(text, title)
        elif kind in {"relationship", "habit", "family"}:
            text = enrich_standard(text, title)
        if 'data-quality="enriched-v2"' not in text:
            text = text.replace('<section class="article-section"><h2>خطأ شائع</h2>', contextual_section(title) + '<section class="article-section"><h2>خطأ شائع</h2>', 1)
        path.write_text(text, encoding="utf-8")
        changed += 1

    index_path = OUT / "index.html"
    index_path.write_text(add_analytics(index_path.read_text(encoding="utf-8")), encoding="utf-8")
    keep_homepage_outline_concise()
    if comparisons != 35 or len(COMPARISON_NOTES) != 35:
        raise SystemExit(f"Comparison contract mismatch: enriched={comparisons}, notes={len(COMPARISON_NOTES)}")
    print({"enriched_pages": changed, "pair_specific_comparisons": comparisons, "analytics_pages": changed + 1, "quality_marker": "enriched-v2"})


if __name__ == "__main__":
    main()
